        assert_eq!(outcome.report.cleanup_inputs(), 0);
        assert!(outcome.report.replay_recorded());
        assert!(runtime.is_paused());
        assert!(!runtime
            .input_debug_snapshot()
            .keyboard
            .iter()
            .any(|key| key == "KeyW"));
    }

